import { createRoute, z } from '@hono/zod-openapi'

const StringSchema = z.string().openapi('String')

const TStampSchema = z.iso.datetime({ offset: true }).openapi('TStamp')

const PendingMaintenanceActionSchema = z
  .object({
    Action: StringSchema.and(
      z
        .any()
        .openapi({
          description:
            'The type of pending maintenance action that is available for the resource. Valid actions are <code>system-update</code>, <code>db-upgrade</code>, <code>hardware-maintenance</code>, and <code>ca-certificate-rotation</code>.',
        }),
    ).exactOptional(),
    AutoAppliedAfterDate: TStampSchema.and(
      z
        .any()
        .openapi({
          description:
            'The date of the maintenance window when the action is applied. The maintenance action is applied to the resource during its first maintenance window after this date.',
        }),
    ).exactOptional(),
    ForcedApplyDate: TStampSchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>The date when the maintenance action is automatically applied.</p> <p>On this date, the maintenance action is applied to the resource as soon as possible, regardless of the maintenance window for the resource. There might be a delay of one or more days from this date before the maintenance action is applied.</p>',
        }),
    ).exactOptional(),
    OptInStatus: StringSchema.and(
      z
        .any()
        .openapi({
          description:
            'Indicates the type of opt-in request that has been received for the resource.',
        }),
    ).exactOptional(),
    CurrentApplyDate: TStampSchema.and(
      z
        .any()
        .openapi({
          description:
            'The effective date when the pending maintenance action is applied to the resource. This date takes into account opt-in requests received from the <code>ApplyPendingMaintenanceAction</code> API, the <code>AutoAppliedAfterDate</code>, and the <code>ForcedApplyDate</code>. This value is blank if an opt-in request has not been received and nothing has been specified as <code>AutoAppliedAfterDate</code> or <code>ForcedApplyDate</code>.',
        }),
    ).exactOptional(),
    Description: StringSchema.and(
      z
        .any()
        .openapi({
          description: 'A description providing more detail about the maintenance action.',
        }),
    ).exactOptional(),
  })
  .openapi({
    description: 'Provides information about a pending maintenance action for a resource.',
    required: [],
  })
  .openapi('PendingMaintenanceAction')

const PendingMaintenanceActionDetailsSchema = z
  .array(
    PendingMaintenanceActionSchema.and(
      z.any().openapi({ xml: { name: 'PendingMaintenanceAction' } }),
    ),
  )
  .openapi('PendingMaintenanceActionDetails')

const ResourcePendingMaintenanceActionsSchema = z
  .object({
    ResourceIdentifier: StringSchema.and(
      z
        .any()
        .openapi({ description: 'The ARN of the resource that has pending maintenance actions.' }),
    ).exactOptional(),
    PendingMaintenanceActionDetails: PendingMaintenanceActionDetailsSchema.and(
      z
        .any()
        .openapi({
          description:
            'A list that provides details about the pending maintenance actions for the resource.',
        }),
    ).exactOptional(),
  })
  .openapi({
    description: 'Describes the pending maintenance actions for a resource.',
    required: [],
  })
  .openapi('ResourcePendingMaintenanceActions')

type PendingMaintenanceActionsType = (z.infer<typeof ResourcePendingMaintenanceActionsSchema> & {
  [key: string]: unknown
})[]

