const ExportTaskSchema = z
  .object({
    ExportTaskIdentifier: StringSchema.and(
      z
        .any()
        .openapi({
          description:
            "A unique identifier for the snapshot or cluster export task. This ID isn't an identifier for the Amazon S3 bucket where the data is exported.",
        }),
    ).exactOptional(),
    SourceArn: StringSchema.and(
      z
        .any()
        .openapi({
          description:
            'The Amazon Resource Name (ARN) of the snapshot or cluster exported to Amazon S3.',
        }),
    ).exactOptional(),
    ExportOnly: StringListSchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>The data exported from the snapshot or cluster. Valid values are the following:</p> <ul> <li> <p> <code>database</code> - Export all the data from a specified database.</p> </li> <li> <p> <code>database.table</code> <i>table-name</i> - Export a table of the snapshot or cluster. This format is valid only for RDS for MySQL, RDS for MariaDB, and Aurora MySQL.</p> </li> <li> <p> <code>database.schema</code> <i>schema-name</i> - Export a database schema of the snapshot or cluster. This format is valid only for RDS for PostgreSQL and Aurora PostgreSQL.</p> </li> <li> <p> <code>database.schema.table</code> <i>table-name</i> - Export a table of the database schema. This format is valid only for RDS for PostgreSQL and Aurora PostgreSQL.</p> </li> </ul>',
        }),
    ).exactOptional(),
    SnapshotTime: TStampSchema.and(
      z.any().openapi({ description: 'The time that the snapshot was created.' }),
    ).exactOptional(),
    TaskStartTime: TStampSchema.and(
      z
        .any()
        .openapi({ description: 'The time that the snapshot or cluster export task started.' }),
    ).exactOptional(),
    TaskEndTime: TStampSchema.and(
      z.any().openapi({ description: 'The time that the snapshot or cluster export task ended.' }),
    ).exactOptional(),
    S3Bucket: StringSchema.and(
      z
        .any()
        .openapi({
          description: 'The Amazon S3 bucket that the snapshot or cluster is exported to.',
        }),
    ).exactOptional(),
    S3Prefix: StringSchema.and(
      z
        .any()
        .openapi({
          description:
            'The Amazon S3 bucket prefix that is the file name and path of the exported data.',
        }),
    ).exactOptional(),
    IamRoleArn: StringSchema.and(
      z
        .any()
        .openapi({
          description:
            'The name of the IAM role that is used to write to Amazon S3 when exporting a snapshot or cluster.',
        }),
    ).exactOptional(),
    KmsKeyId: StringSchema.and(
      z
        .any()
        .openapi({
          description:
            "The key identifier of the Amazon Web Services KMS key that is used to encrypt the data when it's exported to Amazon S3. The KMS key identifier is its key ARN, key ID, alias ARN, or alias name. The IAM role used for the export must have encryption and decryption permissions to use this KMS key.",
        }),
    ).exactOptional(),
    Status: StringSchema.and(
      z
        .any()
        .openapi({
          description:
            '<p>The progress status of the export task. The status can be one of the following:</p> <ul> <li> <p> <code>CANCELED</code> </p> </li> <li> <p> <code>CANCELING</code> </p> </li> <li> <p> <code>COMPLETE</code> </p> </li> <li> <p> <code>FAILED</code> </p> </li> <li> <p> <code>IN_PROGRESS</code> </p> </li> <li> <p> <code>STARTING</code> </p> </li> </ul>',
        }),
    ).exactOptional(),
    PercentProgress: IntegerSchema.and(
      z
        .any()
        .openapi({
          description: 'The progress of the snapshot or cluster export task as a percentage.',
        }),
    ).exactOptional(),
    TotalExtractedDataInGB: IntegerSchema.and(
      z.any().openapi({ description: 'The total amount of data exported, in gigabytes.' }),
    ).exactOptional(),
    FailureCause: StringSchema.and(
      z.any().openapi({ description: 'The reason the export failed, if it failed.' }),
    ).exactOptional(),
    WarningMessage: StringSchema.and(
      z.any().openapi({ description: 'A warning about the snapshot or cluster export task.' }),
    ).exactOptional(),
    SourceType: ExportSourceTypeSchema.and(
      z.any().openapi({ description: 'The type of source for the export.' }),
    ).exactOptional(),
  })
  .openapi({
    description:
      '<p>Contains the details of a snapshot or cluster export to Amazon S3.</p> <p>This data type is used as a response element in the <code>DescribeExportTasks</code> action.</p>',
    required: [],
  })
  .openapi('ExportTask')

