export const getActionDownloadDBLogFilePortionRoute = createRoute({
  method: 'get',
  path: '/#Action=DownloadDBLogFilePortion',
  description:
    "<p>Downloads all or a portion of the specified log file, up to 1 MB in size.</p> <p>This command doesn't apply to RDS Custom.</p>",
  operationId: 'GET_DownloadDBLogFilePortion',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z.object({
      DBInstanceIdentifier: z
        .string()
        .openapi({
          param: {
            name: 'DBInstanceIdentifier',
            in: 'query',
            required: true,
            description:
              '<p>The customer-assigned name of the DB instance that contains the log files you want to list.</p> <p>Constraints:</p> <ul> <li> <p>Must match the identifier of an existing DBInstance.</p> </li> </ul>',
            schema: { type: 'string' },
          },
        }),
      LogFileName: z
        .string()
        .openapi({
          param: {
            name: 'LogFileName',
            in: 'query',
            required: true,
            description: 'The name of the log file to be downloaded.',
            schema: { type: 'string' },
          },
        }),
      Marker: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'Marker',
            in: 'query',
            required: false,
            description:
              'The pagination token provided in the previous request or "0". If the Marker parameter is specified the response includes only records beyond the marker until the end of the file or up to NumberOfLines.',
            schema: { type: 'string' },
          },
        }),
      NumberOfLines: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'NumberOfLines',
            in: 'query',
            required: false,
            description:
              '<p>The number of lines to download. If the number of lines specified results in a file over 1 MB in size, the file is truncated at 1 MB in size.</p> <p>If the NumberOfLines parameter is specified, then the block of lines returned can be from the beginning or the end of the log file, depending on the value of the Marker parameter.</p> <ul> <li> <p>If neither Marker or NumberOfLines are specified, the entire log file is returned up to a maximum of 10000 lines, starting with the most recent log entries first.</p> </li> <li> <p>If NumberOfLines is specified and Marker isn\'t specified, then the most recent lines from the end of the log file are returned.</p> </li> <li> <p>If Marker is specified as "0", then the specified number of lines from the beginning of the log file are returned.</p> </li> <li> <p>You can download the log file in blocks of lines by specifying the size of the block using the NumberOfLines parameter, and by specifying a value of "0" for the Marker parameter in your first request. Include the Marker value returned in the response as the Marker value for the next request, continuing until the AdditionalDataPending response element returns false.</p> </li> </ul>',
            schema: { type: 'integer' },
          },
        }),
      Action: z
        .literal('DownloadDBLogFilePortion')
        .openapi({
          param: {
            name: 'Action',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['DownloadDBLogFilePortion'] },
          },
        }),
      Version: z
        .literal('2014-10-31')
        .openapi({
          param: {
            name: 'Version',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['2014-10-31'] },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'text/xml': { schema: DownloadDBLogFilePortionDetailsSchema } },
    },
    480: {
      description: 'DBInstanceNotFoundFault',
      content: { 'text/xml': { schema: DBInstanceNotFoundFaultSchema } },
    },
    481: {
      description: 'DBLogFileNotFoundFault',
      content: { 'text/xml': { schema: DBLogFileNotFoundFaultSchema } },
    },
  },
})

