export const getActionSwitchoverBlueGreenDeploymentRoute = createRoute({
  method: 'get',
  path: '/#Action=SwitchoverBlueGreenDeployment',
  description:
    '<p>Switches over a blue/green deployment.</p> <p>Before you switch over, production traffic is routed to the databases in the blue environment. After you switch over, production traffic is routed to the databases in the green environment.</p> <p>For more information, see <a href="https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/blue-green-deployments.html">Using Amazon RDS Blue/Green Deployments for database updates</a> in the <i>Amazon RDS User Guide</i> and <a href="https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/blue-green-deployments.html">Using Amazon RDS Blue/Green Deployments for database updates</a> in the <i>Amazon Aurora User Guide</i>.</p>',
  operationId: 'GET_SwitchoverBlueGreenDeployment',
  request: {
    headers: z.object({
      'X-Amz-Content-Sha256': XAmzContentSha256ParamsSchema,
      'X-Amz-Date': XAmzDateParamsSchema,
      'X-Amz-Algorithm': XAmzAlgorithmParamsSchema,
      'X-Amz-Credential': XAmzCredentialParamsSchema,
      'X-Amz-Security-Token': XAmzSecurityTokenParamsSchema,
      'X-Amz-Signature': XAmzSignatureParamsSchema,
      'X-Amz-SignedHeaders': XAmzSignedHeadersParamsSchema,
    }),
    query: z.object({
      BlueGreenDeploymentIdentifier: z
        .string()
        .regex(/[A-Za-z][0-9A-Za-z-:._]*/)
        .min(1)
        .max(255)
        .openapi({
          param: {
            name: 'BlueGreenDeploymentIdentifier',
            in: 'query',
            required: true,
            description:
              '<p>The unique identifier of the blue/green deployment.</p> <p>Constraints:</p> <ul> <li> <p>Must match an existing blue/green deployment identifier.</p> </li> </ul>',
            schema: {
              type: 'string',
              pattern: '[A-Za-z][0-9A-Za-z-:._]*',
              minLength: 1,
              maxLength: 255,
            },
          },
        }),
      SwitchoverTimeout: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(30),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'SwitchoverTimeout',
            in: 'query',
            required: false,
            description:
              '<p>The amount of time, in seconds, for the switchover to complete.</p> <p>Default: 300</p> <p>If the switchover takes longer than the specified duration, then any changes are rolled back, and no changes are made to the environments.</p>',
            schema: { type: 'integer', minimum: 30 },
          },
        }),
      Action: z
        .literal('SwitchoverBlueGreenDeployment')
        .openapi({
          param: {
            name: 'Action',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['SwitchoverBlueGreenDeployment'] },
          },
        }),
      Version: z
        .literal('2014-10-31')
        .openapi({
          param: {
            name: 'Version',
            in: 'query',
            required: true,
            schema: { type: 'string', enum: ['2014-10-31'] },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success',
      content: { 'text/xml': { schema: SwitchoverBlueGreenDeploymentResponseSchema } },
    },
    480: {
      description: 'BlueGreenDeploymentNotFoundFault',
      content: { 'text/xml': { schema: BlueGreenDeploymentNotFoundFaultSchema } },
    },
    481: {
      description: 'InvalidBlueGreenDeploymentStateFault',
      content: { 'text/xml': { schema: InvalidBlueGreenDeploymentStateFaultSchema } },
    },
  },
})

